SELECT m.organization_id AS org, m.notice_id AS notice, m.section_id AS sec, m.name AS mname, r.field_id AS role, r.value AS ref, m2.organization_id AS ref_org, m2.name AS ref_name FROM organization_mentions m CROSS JOIN notice_ids r ON r.notice_id = m.notice_id CROSS JOIN organization_mentions m2 ON m2.notice_id = r.notice_id AND m2.section_id = r.value WHERE m.organization_id = 30953692 AND +m.name NOT LIKE 'Northern Housing%' AND +r.is_ref = 1 AND +r.field_id LIKE 'OPT-30%'
UNION ALL
